 p=Path(path);rows.append(dict(tic=tic,seed=json.loads(p.read_text())['best'],seed_path=str(p),seed_sha256=sha(p),inputs=[dict(sector=s,path=str(q:=Path(f'data/qlp/{tic}-s{s:04d}.fits')),sha256=sha(q),provenance=json.loads(Path(str(q)+'.json').read_text())) for s in sectors]))
